var n=`0609-baghrir`;var a=`world-0609`;var t=`MA`;var r=`northern-africa`;var o=8;var s=74;var l={en:`Baghrir`,ua:`Багрір`};var g={en:`Baghrir is a Morocco classic prepared with semolina flour, all-purpose flour, instant yeast, baking powder. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Baghrir requires a light airy semolina batter and one-sided cooking; this is a homemade yeast version.`,ua:`Багрір, страва кухні країни Марокко зі складниками: семоліна, пшеничне борошно універсальне, інстантні дріжджі, розпушувач тіста. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Багрір готують із пухирчастого манного тіста й смажать лише з одного боку; тут домашній дріжджовий варіант.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`semolina-flour`,270,`g`],[`all-purpose-flour`,90,`g`],[`instant-yeast`,6,`g`],[`baking-powder`,6,`g`],[`water`,650,`ml`],[`white-granulated-sugar`,20,`g`]]},{en:`Cover the batter loosely and leave in a suitable warm, clean place for about 40 minutes to become bubbly and lightly tangy; do not refrigerate during active fermentation.`,ua:`Нещільно накрийте тісто й залиште приблизно на 40 хвилин у чистому теплому місці до появи бульбашок і легкої кислинки; під час активного бродіння не ставте в холодильник.`,t:[`sourdough-fermentation`],m:40,i:[]},{en:`Pour small rounds of bubbly batter into a medium-hot nonstick pan; cook baghrir on ONE side only until many holes appear and the surface is dry.`,ua:`Наливайте невеликі порції пухирчастого тіста на середньо гарячу антипригарну сковороду; смажте багрір ЛИШЕ з одного боку до появи численних дірочок і сухої поверхні.`,t:[`griddle-cooking`],m:22,i:[[`sunflower-oil`,12,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`unsalted-butter`,60,`g`],[`honey`,100,`g`]]}];var d={slug:n,id:a,country:`MA`,region:r,servings:8,minutes:74,title:l,text:g,steps:u};export{t as country,d as default,a as id,s as minutes,r as region,o as servings,n as slug,u as steps,g as text,l as title};